import { chromium } from 'playwright'; import fs from 'fs'; import path from 'path';
const BASE='https://www.statesideqm.com', THEME='158900125851', OUT='sep18-grid-perf-verify'; fs.mkdirSync(path.join(OUT,'screenshots'),{recursive:true});
const routes=[['Accessories','/collections/accessories-gifts-collectibles'],['Airsoft','/collections/airsoft-milsim'],['Apparel','/collections/apparel'],['State Guard Root','/collections/state-guard-series']];
const sleep=ms=>new Promise(r=>setTimeout(r,ms)); const browser=await chromium.launch({headless:true}); const ctx=await browser.newContext({viewport:{width:1440,height:1000}}); const page=await ctx.newPage();page.setDefaultNavigationTimeout(70000);
let response=await page.goto(BASE+'/?preview_theme_id='+THEME,{waitUntil:'domcontentloaded',timeout:70000}); await page.waitForLoadState('load',{timeout:15000}).catch(()=>{});await sleep(1500);
const established=await page.evaluate(()=>({id:String(window.Shopify?.theme?.id||''),name:String(window.Shopify?.theme?.name||'')}));if(established.id!==THEME)throw new Error('wrong preview '+JSON.stringify(established));
const rows=[];
for(let i=0;i<routes.length;i++){const [label,route]=routes[i];const requested=[];const onReq=r=>{if(r.resourceType()==='fetch'||r.resourceType()==='xhr')requested.push(r.url())};page.on('request',onReq);
 response=await page.goto(BASE+route,{waitUntil:'domcontentloaded',timeout:70000});await page.waitForLoadState('load',{timeout:16000}).catch(()=>{});await sleep(1400);page.off('request',onReq);
 const row=await page.evaluate(({label,route,requested,themeId})=>{const n=performance.getEntriesByType('navigation')[0],rs=performance.getEntriesByType('resource'),f=performance.getEntriesByName('first-contentful-paint')[0],main=document.getElementById('MainContent'),grid=document.querySelector('[data-testid="product-grid"]');return{label,route,statusTitle:document.title,theme:{id:String(window.Shopify?.theme?.id||''),name:String(window.Shopify?.theme?.name||'')},ttfbMs:Math.round(n?.responseStart||0),dclMs:Math.round(n?.domContentLoadedEventEnd||0),loadMs:Math.round(n?.loadEventEnd||0),fcpMs:Math.round(f?.startTime||0),resources:rs.length,transferBytes:rs.reduce((s,r)=>s+(r.transferSize||0),0),domNodes:document.getElementsByTagName('*').length,styles:document.querySelectorAll('style').length,stylesheets:document.styleSheets.length,scripts:document.scripts.length,images:document.images.length,productCards:document.querySelectorAll('[data-testid="product-grid"] .product-grid__item').length,mainNodes:main?.getElementsByTagName('*').length||0,stateGuardRoot:document.querySelectorAll('[data-sq-state-guard-root]').length,page2Requests:requested.filter(u=>/[?&]page=2(?:&|$)/.test(u)),sectionFetches:requested.filter(u=>u.includes('section_id=')),h1:(document.querySelector('h1')?.textContent||'').replace(/\s+/g,' ').trim(),previewOk:String(window.Shopify?.theme?.id||'')===themeId}}, {label,route,requested,themeId:THEME});
 row.httpStatus=response?.status()??null;rows.push(row);console.log('GRIDVERIFY',JSON.stringify(row));await page.screenshot({path:path.join(OUT,'screenshots',String(i+1).padStart(2,'0')+'-'+label.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'.png'),fullPage:false});await sleep(5000)}
fs.writeFileSync(path.join(OUT,'results.json'),JSON.stringify({generatedAt:new Date().toISOString(),established,rows},null,2));console.log('SUMMARY',JSON.stringify(rows.map(x=>({label:x.label,http:x.httpStatus,preview:x.previewOk,ttfb:x.ttfbMs,dcl:x.dclMs,load:x.loadMs,fcp:x.fcpMs,kb:Math.round(x.transferBytes/1024),resources:x.resources,dom:x.domNodes,styles:x.styles,scripts:x.scripts,cards:x.productCards,page2:x.page2Requests.length,stateGuardRoot:x.stateGuardRoot}))));
await ctx.close();await browser.close();